//! Checks the Gaussian blur against ImageJ's own output.
//!
//! Fixture generated by `parity/java/GaussianBlur.java` via `./parity/record.sh`,
//! recorded through `FloatProcessor.blurGaussian(sigma)` — the call
//! `WatershedCellDetection` makes before taking its Laplacian and finding
//! maxima. Needs no slide.
//!
//! Two halves are compared separately, because a per-pixel comparison alone
//! would not say which was wrong:
//!
//! - the kernel from `makeGaussianKernel`, which pins the accuracy constant,
//!   the parabolic tail and the break-point search that picks where it starts;
//! - whole blurred images, which pin the convolution, its edge extension, its
//!   float accumulation order, and the downscale/upscale path above sigma 8.5.

use qupath_filters::{GaussianBlur, gaussian_kernel};

/// Relative tolerance, per `parity/README.md`.
///
/// Both sides do the same `f32` arithmetic in the same order, so the only
/// slack is `exp`, `ln` and `sqrt`, where Java's `Math` and Rust's libm are
/// each allowed to differ by an ulp before the result is narrowed to `f32`.
/// The assertions report the worst seen rather than only that they passed.
const TOLERANCE: f64 = 1e-5;

/// Values below this are compared absolutely rather than relatively.
///
/// Blurred optical density passes through zero — the input runs negative, as
/// it does on a real slide — and relative error is unbounded there for reasons
/// that say nothing about correctness.
const NEAR_ZERO: f64 = 1e-6;

/// ImageJ's accuracy for a `FloatProcessor`, which is what detection blurs.
const FLOAT_ACCURACY: f64 = 0.0002;

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../parity/fixtures/GaussianBlur.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

/// Parses a float list. Java writes `Float.toString`, which round-trips
/// exactly, so these are the same bits ImageJ held.
fn floats(text: &str) -> Vec<f32> {
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

/// Compares one series against ImageJ's, returning the worst relative error.
fn compare(ours: &[f32], theirs: &[f32], what: &str) -> f64 {
    assert_eq!(
        ours.len(),
        theirs.len(),
        "{what}: {} values against ImageJ's {}",
        ours.len(),
        theirs.len()
    );

    let mut worst = 0.0f64;
    let mut exact = 0usize;
    for (index, (&ours, &theirs)) in ours.iter().zip(theirs).enumerate() {
        if ours.to_bits() == theirs.to_bits() {
            exact += 1;
        }
        let (ours, theirs) = (f64::from(ours), f64::from(theirs));
        let difference = (ours - theirs).abs();
        let relative = if theirs.abs() > NEAR_ZERO {
            difference / theirs.abs()
        } else {
            difference
        };
        assert!(
            relative <= TOLERANCE,
            "{what}: at {index} we have {ours}, ImageJ has {theirs} \
             (relative {relative:.3e})"
        );
        worst = worst.max(relative);
    }

    // Every value has matched ImageJ bit for bit so far, which is a stronger
    // statement than the tolerance and worth seeing erode before it fails.
    // It is reported rather than asserted: the kernel goes through `exp`,
    // `ln` and `sqrt`, where Java's `Math` and the platform libm are each
    // allowed an ulp, and a build where that showed through would still be
    // correct. The tolerance is the gate.
    if exact != ours.len() {
        println!(
            "  note: {what}: {} of {} values are no longer bit-identical",
            ours.len() - exact,
            ours.len()
        );
    }
    worst
}

#[test]
fn matches_imagej_gaussian_kernels() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));

    let (kernels, _) = between(&text, "\"kernels\": [", "\n  ],", 0);

    let mut cases = 0usize;
    let mut worst = 0.0f64;
    let mut at = 0usize;
    while let Some(start) = kernels[at..].find("{\"sigma\": ") {
        let from = at + start;
        let (sigma, next) = scalar(kernels, "sigma", from);
        let (accuracy, next) = scalar(kernels, "accuracy", next);
        let (max_radius, next) = scalar(kernels, "maxRadius", next);
        let (kernel_text, next) = between(kernels, "\"kernel\": [", "]", next);
        let (sum_text, next) = between(kernels, "\"kernSum\": [", "]", next);
        at = next;

        // The accuracy is the constant a port is most likely to take from the
        // wrong branch: `blurGaussian` picks 0.002 for byte and colour images
        // and this for float, and the looser value shortens every kernel.
        assert_eq!(
            accuracy, FLOAT_ACCURACY,
            "the fixture was recorded at accuracy {accuracy}, not the {FLOAT_ACCURACY} \
             a FloatProcessor gets"
        );

        #[expect(
            clippy::cast_possible_truncation,
            clippy::cast_sign_loss,
            reason = "recorded maxRadius is a small positive integer"
        )]
        let (ours_kernel, ours_sum) = gaussian_kernel(sigma, accuracy, max_radius as usize);
        let label = format!("kernel sigma {sigma} maxRadius {max_radius}");

        // The radius is an integer decision — how many taps the accuracy
        // demands — so it is asserted exactly rather than within a tolerance.
        // Getting it wrong by one shifts every normalised value slightly, which
        // a loose per-value comparison could absorb.
        assert_eq!(
            ours_kernel.len(),
            floats(kernel_text).len(),
            "{label}: radius {} against ImageJ's {}",
            ours_kernel.len(),
            floats(kernel_text).len()
        );

        worst = worst.max(compare(&ours_kernel, &floats(kernel_text), &label));
        worst = worst.max(compare(
            &ours_sum,
            &floats(sum_text),
            &format!("kernSum sigma {sigma} maxRadius {max_radius}"),
        ));
        cases += 1;
    }

    assert!(cases >= 10, "only {cases} kernels in the fixture");
    println!("{cases} kernels  worst relative {worst:.3e}");
}

#[test]
fn matches_imagej_blurred_images() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));

    let (images, _) = between(&text, "\"images\": [", "\n  ]\n}", 0);

    let mut cases = 0usize;
    let mut overall = 0.0f64;
    let mut at = 0usize;
    let mut blur = GaussianBlur::new();
    while let Some(start) = images[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(images, "\"name\": \"", "\"", from);
        let (width, next) = scalar(images, "width", next);
        let (height, next) = scalar(images, "height", next);
        let (sigma, next) = scalar(images, "sigma", next);
        let (input_text, next) = between(images, "\"in\": [", "]", next);
        let (output_text, next) = between(images, "\"out\": [", "]", next);
        at = next;

        #[expect(
            clippy::cast_possible_truncation,
            clippy::cast_sign_loss,
            reason = "recorded dimensions are small positive integers"
        )]
        let (width, height) = (width as usize, height as usize);

        let mut ours = floats(input_text);
        assert_eq!(
            ours.len(),
            width * height,
            "{name}: {} input values for {width}x{height}",
            ours.len()
        );

        // Reusing one blur across every case on purpose: a stale buffer left by
        // a previous shape or sigma would show up here and nowhere else.
        blur.blur(&mut ours, width, sigma);

        let worst = compare(
            &ours,
            &floats(output_text),
            &format!("{name} ({width}x{height}, sigma {sigma})"),
        );
        println!("{name:>18}  {width:>3}x{height:<3} sigma {sigma:<4}  worst relative {worst:.3e}");
        overall = overall.max(worst);
        cases += 1;
    }

    assert!(cases >= 12, "only {cases} images in the fixture");

    // The downscale/upscale path above sigma 8.5 is separate code reached by
    // nothing but a large sigma; if the fixture ever loses those cases the
    // whole branch would go unchecked while the test still passed.
    for name in ["downscale-sigma9", "downscale-sigma12", "downscale-short"] {
        assert!(
            images.contains(name),
            "{name} missing: the large-sigma path is unchecked"
        );
    }

    println!("{cases} images  worst relative {overall:.3e}");
}
